def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)

    seen = [[False] * w for _ in range(h)]
    components = []
    core_colors = {background}

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            if len(cells) >= 6:
                core_colors.add(color)
                if color != background:
                    r0 = min(y for y, x in cells)
                    r1 = max(y for y, x in cells)
                    c0 = min(x for y, x in cells)
                    c1 = max(x for y, x in cells)
                    density = len(cells) / ((r1 - r0 + 1) * (c1 - c0 + 1))
                    if density >= 0.65:
                        components.append((color, cells, r0, r1, c0, c1))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in core_colors:
                continue

            boxes = [
                comp for comp in components
                if comp[2] <= r <= comp[3] and comp[4] <= c <= comp[5]
            ]
            if boxes:
                def distance(comp):
                    return min(abs(r - y) + abs(c - x) for y, x in comp[1])
                out[r][c] = min(boxes, key=distance)[0]
                continue

            votes = {}
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] in core_colors:
                    color = grid[nr][nc]
                    votes[color] = votes.get(color, 0) + 1
            if votes:
                best = max(votes.values())
                winners = [color for color, n in votes.items() if n == best]
                out[r][c] = winners[0] if len(winners) == 1 else background
            else:
                out[r][c] = background

    return out
